"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 time-resolved ears diagnostic (docs/iterations.md, 2026-11-20: design, decision rule and expectation fixed before
running; the author approved step 1). Probes only: no system training, no API; train and dev only, test and replication
untouched.

Question: after step 2c the stop decision is grounded in 0.54 of the S-move groups and the ears-only probe in 0.60, while
the leaving version ranks first within its group in 99% of pairs. Is the missing part lost when the 8 s of audio tokens
are summarised into one mean and one max (what happened just now, and in what order), or does the encoder not carry it?

extract: VoxTurn's AuT encoder (official frozen model; our LoRA sits on the language model only) cuts the 8 s window
  into eight 1 s chunks of 13 tokens (104 tokens, d = 1,024); the window ends at the decision point. Per window and per
  second: the mean and the max of its 13 tokens (fp16). Train: the S-move windows with a stop answer and the R-hear
  windows with a respond answer (the probe's sets); dev: all windows. Checks: the whole-window mean and max rebuilt from
  the per-second values against the stored ears (train: feats_train_allclass.npz; dev: the grounding package's
  l1_none.npz).
probe: as scripts/p1v4_smove_diag_dev.py (standardised features, LogisticRegression C = 0.1), one probe per pooling and
  part, scored on the dev grounding groups. Poolings: whole (= the current ears), seg3 (primary: last 1 s, the 2 s
  before, the first 5 s), last1 and sec8 (reported only). Group all-right at the 0.5 cut with three-way cluster
  bootstrap intervals, the best cut, AUC of version 1 against the others, within-group concordance per pair, hit rate
  and false alarms at the 0.5 cut; the decision rule as logged.
Outputs: data/p1v4/runs/ears_time/feats_{train,dev}.npz; results/main_v04/ears_time_diag_dev.json
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_ears_time_diag.py extract|probe
"""
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_grounding_report as GR  # noqa: E402

OUT = "data/p1v4/runs/ears_time"
RES = "results/main_v04/ears_time_diag_dev.json"
TASK = {"s_move": "S", "r_hear": "R"}
YES = {"S": "stop", "R": "respond"}
POOLINGS = ("whole", "seg3", "last1", "sec8")
SEG3 = ((7, 8), (5, 7), (0, 5))            # seconds of the window: last 1 s, the 2 s before, the first 5 s


def extract():
    import soundfile as sf
    import torch
    import l1_voxturn
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    _, vt = l1_voxturn.load_official()
    for which in ("train", "dev"):
        wins = D.windows_of(D.load_rows(which), which)
        if which == "train":
            wins = [w for w in wins if w["part"] in TASK and w["gold"].get(TASK[w["part"]]) is not None]
        SM, SX, WH = [], [], []
        t0 = time.time()
        B = 8
        for i in range(0, len(wins), B):
            chunk = wins[i:i + B]
            waves = torch.stack([torch.from_numpy(sf.read(w["path"], dtype="float32")[0]) for w in chunk]).cuda()
            with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
                audio = vt.encode_audio(vt.mel(waves))
            a = audio.float()
            assert a.shape[1] == 104, a.shape
            s = a.view(a.shape[0], 8, 13, a.shape[2])
            SM.append(s.mean(2).cpu().numpy().astype(np.float16))
            SX.append(s.amax(2).cpu().numpy().astype(np.float16))
            WH.append(torch.cat([a.mean(1), a.amax(1)], -1).cpu().numpy().astype(np.float16))
            if (i // B) % 500 == 0:
                print(f"{which}: {i + len(chunk)}/{len(wins)} windows {time.time() - t0:.0f} s", flush=True)
        y = [int(w["gold"][TASK[w["part"]]] == YES[TASK[w["part"]]]) if w["part"] in TASK
             and w["gold"].get(TASK[w["part"]]) is not None else -1 for w in wins]
        np.savez(f"{OUT}/feats_{which}.npz", ids=np.array([w["id"] for w in wins]),
                 parts=np.array([w["part"] for w in wins]), y=np.array(y), sec_mean=np.concatenate(SM),
                 sec_max=np.concatenate(SX), whole=np.concatenate(WH))
        print(f"{which} done: {len(wins)} windows, {time.time() - t0:.0f} s", flush=True)
    check()


def check():
    """The whole-window ears rebuilt here against the stored ones (same windows by id)."""
    out = {}
    for which, path in (("train", f"{G.R}/grounding/allclass/feats_train_allclass.npz"),
                        ("dev", f"{G.out_dir('dev')}/l1_none.npz")):
        z = np.load(f"{OUT}/feats_{which}.npz")
        old = np.load(path, mmap_mode="r")
        pos = {i: n for n, i in enumerate(old["ids"])}
        idx = [n for n, i in enumerate(z["ids"]) if i in pos]
        a = z["whole"][idx].astype(np.float32)
        b = np.asarray(old["ears"][[pos[z["ids"][n]] for n in idx]], dtype=np.float32)
        sm, sx = z["sec_mean"][idx].astype(np.float32), z["sec_max"][idx].astype(np.float32)
        rebuilt = np.concatenate([sm.mean(1), sx.max(1)], 1)
        out[which] = {"n_matched": len(idx), "n_windows": int(len(z["ids"])),
                      "max_abs_diff_vs_stored": float(np.abs(a - b).max()),
                      "median_abs_diff_vs_stored": float(np.median(np.abs(a - b))),
                      "max_abs_rebuilt_vs_whole": float(np.abs(rebuilt - a).max()),
                      "mean_abs_value": float(np.abs(b).mean())}
        print(f"check {which}: {out[which]}", flush=True)
    json.dump(out, open(f"{OUT}/check.json", "w"), indent=1)
    return out


def pool(sm, sx, kind):
    """sm, sx: (N, 8, d) per-second mean and max -> features of one pooling (seconds hold 13 tokens each, so the mean of
    second means is the token mean)."""
    if kind == "whole":
        return np.concatenate([sm.mean(1), sx.max(1)], 1)
    if kind == "seg3":
        return np.concatenate([np.concatenate([sm[:, a:b].mean(1), sx[:, a:b].max(1)], 1) for a, b in SEG3], 1)
    if kind == "last1":
        return np.concatenate([sm[:, 7], sx[:, 7]], 1)
    if kind == "sec8":
        return np.concatenate([sm.reshape(len(sm), -1), sx.reshape(len(sx), -1)], 1)
    raise ValueError(kind)


def auc(pos, neg):
    pos, neg = np.asarray(pos), np.asarray(neg)
    return float(((pos[:, None] > neg[None, :]) + 0.5 * (pos[:, None] == neg[None, :])).mean())


def probe(split="dev", source=None):
    """split, source (package v0.6 15.3, added 2026-11-21): the diagnostic as a described item on another split. With
    source "l1_none" the per-second ears come from the grounding package's batch-1 forward of the matched "none"
    condition (grounding/<split>/l1_none.npz; the audio is each version's own), which exists on test after the package
    run; the output is results/main_v04/ears_time_diag_<split>_l1none.json. The default keeps the original dev run."""
    from sklearn.linear_model import LogisticRegression
    tr = np.load(f"{OUT}/feats_train.npz")
    if source == "l1_none":
        dv = np.load(f"{G.out_dir(split)}/l1_none.npz")
    elif split == "dev":
        dv = np.load(f"{OUT}/feats_dev.npz")
    else:
        raise SystemExit("on test and replication the diagnostic reads the package's l1_none.npz (source l1_none)")
    out_path = RES if source is None else f"results/main_v04/ears_time_diag_{split}_l1none.json"
    drow = {i: n for n, i in enumerate(dv["ids"])}
    rows, _ = G.load(split)
    groups = G.load_groups(split)
    cl = GR.cluster_table(rows, split)
    res = {"split": split, "source": source or "feats_dev.npz", "parts": {}}
    if source is None:
        res["check"] = json.load(open(f"{OUT}/check.json"))
    for part, task in TASK.items():
        m = (tr["parts"] == part) & (tr["y"] >= 0)
        sm_tr, sx_tr = tr["sec_mean"][m].astype(np.float32), tr["sec_max"][m].astype(np.float32)
        y = tr["y"][m]
        gs = [g for g in groups if g["part"] == part]
        units = [g["unit"] for g in gs]
        vers = sorted({v for g in gs for v in g["versions"]})
        idx = [[drow[f"{g['unit']}|{v}|{g['k']}"] for v in vers] for g in gs]
        flat = [i for row in idx for i in row]
        sm_dv = dv["sec_mean"][flat].astype(np.float32)
        sx_dv = dv["sec_max"][flat].astype(np.float32)
        ev = 1 if task == "S" else 0                  # the event version's answer: stop (S-move), not respond (R-hear)
        out, right = {}, {}
        for kind in POOLINGS:
            X = pool(sm_tr, sx_tr, kind)
            mu, sd = X.mean(0), X.std(0) + 1e-6
            t0 = time.time()
            clf = LogisticRegression(C=0.1, max_iter=2000).fit((X - mu) / sd, y)
            p1 = clf.predict_proba((pool(sm_dv, sx_dv, kind) - mu) / sd)[:, 1]
            sc = (p1 if ev == 1 else 1 - p1).reshape(len(gs), len(vers))      # event score, versions in `vers` order
            v1 = vers.index("1")
            others = [j for j in range(len(vers)) if j != v1]

            def all_right(cut, sc=sc):
                return (sc[:, v1] >= cut) & np.all(sc[:, others] < cut, 1)
            cuts = np.unique(sc)
            best = max(cuts, key=lambda c: all_right(c).mean())
            r05 = all_right(0.5).astype(float)
            right[kind] = r05
            c = GR.criterion(units, cl, {}, lambda w, a=r05: GR.wmean(w, a), lambda a=r05: float(a.mean()))
            out[kind] = {
                "n_features": int(X.shape[1]), "n_train": int(len(y)), "train_event_share": float(np.mean(y == ev)),
                "fit_s": round(time.time() - t0, 1),
                "group_all_right_0.5": c["point"], "ci95": c["ci95"],
                "group_all_right_best_cut": float(all_right(best).mean()), "best_cut": float(best),
                "auc_v1_vs_others": auc(sc[:, v1], sc[:, others].ravel()),
                "concordance": {f"1_vs_{vers[j]}": float(np.mean((sc[:, v1] > sc[:, j]) + 0.5 * (sc[:, v1] == sc[:, j])))
                                for j in others},
                "hit_v1_0.5": float(np.mean(sc[:, v1] >= 0.5)),
                "false_alarm_0.5": {vers[j]: float(np.mean(sc[:, j] >= 0.5)) for j in others}}
            print(f"{part} {kind:6s} all-right {c['point']:.3f} [{c['ci95'][0]:.3f}, {c['ci95'][1]:.3f}] best "
                  f"{out[kind]['group_all_right_best_cut']:.3f} AUC {out[kind]['auc_v1_vs_others']:.3f} hit "
                  f"{out[kind]['hit_v1_0.5']:.3f} fa {json.dumps({k: round(v, 3) for k, v in out[kind]['false_alarm_0.5'].items()})} "
                  f"conc {json.dumps({k: round(v, 3) for k, v in out[kind]['concordance'].items()})} ({out[kind]['fit_s']} s)",
                  flush=True)
        diffs = {}
        for kind in ("seg3", "last1", "sec8"):
            a, b = right[kind], right["whole"]
            c = GR.criterion(units, cl, {}, lambda w, a=a, b=b: GR.wmean(w, a) - GR.wmean(w, b),
                             lambda a=a, b=b: float(a.mean() - b.mean()))
            diffs[f"{kind} - whole"] = {"point": c["point"], "ci95": c["ci95"],
                                        "meets_rule": bool(c["point"] >= 0.10 and c["ci95"][0] > 0)}
            print(f"{part} {kind} - whole: {c['point']:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}]", flush=True)
        res["parts"][part] = {"n_groups": len(gs), "versions": vers, "poolings": out, "differences": diffs}
    d = res["parts"]["s_move"]["differences"]
    res["decision"] = {"primary seg3 meets the rule (S-move seg3 - whole >= +0.10, lower bound > 0)":
                       d["seg3 - whole"]["meets_rule"],
                       "secondary poolings meeting it (report only)": [k for k in ("last1 - whole", "sec8 - whole")
                                                                       if d[k]["meets_rule"]],
                       "reproduces the earlier probe (S-move 0.60 / AUC 0.966, R-hear 0.79 / 0.979, within 0.02)": {
                           p: [res["parts"][p]["poolings"]["whole"]["group_all_right_0.5"],
                               res["parts"][p]["poolings"]["whole"]["auc_v1_vs_others"]] for p in TASK}}
    json.dump(res, open(out_path, "w"), indent=1)
    print(json.dumps(res["decision"], indent=1))


if __name__ == "__main__":
    if sys.argv[1] == "probe" and len(sys.argv) > 2:          # probe <split> l1_none (package v0.6 15.3)
        probe(sys.argv[2], sys.argv[3] if len(sys.argv) > 3 else None)
    else:
        {"extract": extract, "probe": probe, "check": check}[sys.argv[1]]()
